import java.util.*;

class Solution {
    public int countPrimes(int n) {
        boolean[] composite = new boolean[n];
        for (int p = 2; p * p < n; p++) {
            if (!composite[p]) {
                for (int m = p * p; m < n; m += p) composite[m] = true;
            }
        }
        int count = 0;
        for (int i = 2; i < n; i++) if (!composite[i]) count++;
        return count;
    }
}

